    elements.push(posStart + BigInt(i));
}

// k is 1-based; convert to 0-based index
let kk = k - 1n;

// Build the k-th permutation of 'elements' in lexicographic order
let perm = new Array(limit);
for (let i = 0; i < limit; i++) {
    let blockSize = fact[limit - 1 - i];
    let idx = kk / blockSize;
    kk = kk % blockSize;
