// Now count positions i such that i and a[i] are lucky.
// For positions < posStart, the permutation is identity: a[i] = i.
let ans = 0;

// Count for prefix positions (1 .. posStart-1)
for (let i = 0n; i < luckyIndices.length; i++) {
    let idx = luckyIndices[i];
    if (idx >= posStart) break;
    // a[idx] = idx
    // idx is lucky by construction; check if a[idx] is lucky (same number)
    if (isLucky(Number(idx))) ans++;
}

// Count for suffix positions (posStart .. n)
